// Simulate: fetch user profile asynchronously
// Sleep 500ms, return "User: Alice"
// Block for result with join() and print it

solution.code:
CompletableFuture<String> userFuture = CompletableFuture.supplyAsync(() -> {
    try { Thread.sleep(500); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
    System.out.println("Fetching user... (thread: " + Thread.currentThread().getName() + ")");
    return "User: Alice";
});
System.out.println("Main thread continues while fetching...");
String user = userFuture.join(); // blocks until done
System.out.println("Got: " + user);

