// Step 1: fetchUserId() -> CompletableFuture<Integer> returns 42
// Step 2: fetchProfile(int id) -> CompletableFuture<String> returns "Profile of user 42"
// Chain with thenCompose

solution.code:
java.util.function.Supplier<CompletableFuture<Integer>> fetchUserId = () ->
    CompletableFuture.supplyAsync(() -> {
        try { Thread.sleep(300); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
        return 42;
    });

java.util.function.Function<Integer, CompletableFuture<String>> fetchProfile = id ->
    CompletableFuture.supplyAsync(() -> {
        try { Thread.sleep(300); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
        return "Profile of user " + id;
    });

String profile = fetchUserId.get()
    .thenCompose(fetchProfile)
    .join();
System.out.println(profile); // Profile of user 42

starterCode:
// Fetch user name: "Alice" (300ms)
// Fetch loyalty points: 1500 (400ms)
// Both run in parallel — combine into "Alice has 1500 points"

solution.code:
CompletableFuture<String> nameFuture = CompletableFuture.supplyAsync(() -> {
    try { Thread.sleep(300); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
    return "Alice";
});

CompletableFuture<Integer> pointsFuture = CompletableFuture.supplyAsync(() -> {
    try { Thread.sleep(400); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
    return 1500;
});

long start = System.currentTimeMillis();
String result = nameFuture
    .thenCombine(pointsFuture, (name, points) -> name + " has " + points + " points")
    .join();
System.out.println(result); // Alice has 1500 points
System.out.println("Time: " + (System.currentTimeMillis() - start) + "ms"); // ~400ms

