starterCode:
// Slow future that takes 1000ms
// orTimeout: fail with TimeoutException after 300ms
// completeOnTimeout: return "default" after 300ms instead of failing

solution.code:
// orTimeout — throws TimeoutException
CompletableFuture<String> withTimeout = CompletableFuture
    .supplyAsync(() -> {
        try { Thread.sleep(1000); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
        return "slow result";
    })
    .orTimeout(300, java.util.concurrent.TimeUnit.MILLISECONDS)
    .exceptionally(ex -> "Timed out: " + ex.getCause().getClass().getSimpleName());
System.out.println(withTimeout.join()); // Timed out: TimeoutException

// completeOnTimeout — returns default value
CompletableFuture<String> withDefault = CompletableFuture
    .supplyAsync(() -> {
        try { Thread.sleep(1000); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
        return "slow result";
    })
    .completeOnTimeout("default-after-timeout", 300, java.util.concurrent.TimeUnit.MILLISECONDS);
System.out.println(withDefault.join()); // default-after-timeout

