starterCode:
// Step 1: validateCart() -> CompletableFuture<String> (cartId)
// Step 2: fetchUser() and applyDiscount() in parallel -> combine into order total
// Step 3: placeOrder(total) -> CompletableFuture<String> (orderId)
// Step 4: thenAccept to send confirmation
// Step 5: exceptionally to handle failures

solution.code:
CompletableFuture<String> validateCart = CompletableFuture.supplyAsync(() -> {
    try { Thread.sleep(100); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
    System.out.println("[1] Cart validated");
    return "CART-99";
});

CompletableFuture<String> fetchUser = CompletableFuture.supplyAsync(() -> {
    try { Thread.sleep(200); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
    System.out.println("[2a] User fetched");
    return "Alice";
});

CompletableFuture<Double> applyDiscount = CompletableFuture.supplyAsync(() -> {
    try { Thread.sleep(150); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
    System.out.println("[2b] Discount applied");
    return 89.99;
});

CompletableFuture<String> pipeline = validateCart
    .thenCompose(cartId -> fetchUser.thenCombine(applyDiscount,
        (user, total) -> user + ":" + total + ":" + cartId))
    .thenCompose(info -> CompletableFuture.supplyAsync(() -> {
        System.out.println("[3] Placing order for " + info);
        return "ORDER-" + System.currentTimeMillis();
    }))
    .whenComplete((orderId, ex) -> {
        if (ex == null) System.out.println("[LOG] Order created: " + orderId);
        else System.err.println("[LOG] Failed: " + ex.getMessage());
    })
    .thenApply(orderId -> "Confirmation: " + orderId)
    .exceptionally(ex -> "Checkout failed: " + ex.getCause().getMessage());

System.out.println(pipeline.join());
